<template><section class="mx-auto max-w-7xl px-4 py-14 sm:px-6 lg:px-8"><p class="text-sm uppercase tracking-[0.35em] text-cyan-200">{{ tracks.length }} Workshop Tracks</p><h1 class="mt-4 max-w-4xl text-5xl font-black">Build a working prototype for a real educational challenge.</h1><p class="mt-5 max-w-3xl text-lg leading-8 text-slate-300">Choose a multidisciplinary track, work with technical mentors, and present a responsible AI solution designed for ASEAN learners and institutions.</p><div v-if="pending" class="mt-10 grid gap-5 md:grid-cols-2"><div v-for="n in 4" :key="n" class="h-52 animate-pulse rounded-[2rem] bg-white/5" /></div><div v-else-if="error" class="mt-10 rounded-3xl border border-red-400/30 bg-red-950/30 p-6 text-red-100">Workshop tracks could not be loaded. Reference: {{ requestId || 'unavailable' }}</div><div v-else class="mt-10 grid gap-5 md:grid-cols-2"><article v-for="track in tracks" :key="track.id" class="glass-card rounded-[2rem] p-7"><span class="text-xs uppercase tracking-[0.25em] text-orange-200">Track {{ track.order_index }} · Capacity {{ track.capacity }}</span><h2 class="mt-3 text-2xl font-bold">{{ track.name }}</h2><p class="mt-3 leading-7 text-slate-300">{{ track.description }}</p></article></div><img src="/foto/ai_VR.png" alt="Hands-on AI technology workshop" class="mt-8 h-80 w-full rounded-[2rem] object-cover" /></section></template>
<script setup lang="ts">import {useEvent} from '~/composables/useEvent'; useSeoMeta({title:'Workshop Tracks | ASEAN AI for Education',description:'Five hands-on AI workshop tracks for ASEAN education.'}); const {getEvents,getEventWorkshopTracks}=useEvent(); const {data:response,pending,error}=await useAsyncData('public-workshop-tracks',async()=>{const events=await getEvents(1,1); const event=events.data[0]; if(!event?.slug) throw new Error('Event not found'); return getEventWorkshopTracks(event.slug)}); const tracks=computed(()=>response.value?.data??[]); const requestId=computed(()=>response.value?.request_id);</script>
